import React, { useState, useEffect, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
    Eye,
    Plus,
    X,
    Play,
    Square,
    Trash2,
    Clock,
    Globe,
    User,
    AlertTriangle,
    CheckCircle2,
    Settings,
    Bookmark,
    RefreshCw,
    RotateCcw
} from 'lucide-react';
import { GlassCard, GlassCardContent } from '@/components/ui/GlassCard';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { toast } from 'sonner';

// Sessions Data
const initialSessions = [
    { id: 1, name: 'wallester-reg', status: 'running', url: 'wallester.com', duration: '00:45:32', profile: 'wallester' },
    { id: 2, name: 'gmail-monitor', status: 'idle', url: 'mail.google.com', duration: '02:15:00', profile: 'gmail' },
    { id: 3, name: 'failed-session', status: 'error', url: 'example.com', duration: '00:02:15', profile: 'default', error: 'Connection timeout', retryCount: 0, maxRetries: 3 },
];

// Saved Profiles
const savedProfiles = [
    { name: 'wallester', proxy: true, timeout: 30 },
    { name: 'gmail', proxy: false, timeout: 60 },
    { name: 'default', proxy: false, timeout: 30 },
    { name: 'scraper', proxy: true, timeout: 120 },
];

// Session Logs
const sessionLogs = [
    { time: '14:45:32', type: 'info', message: 'Session started: wallester-reg' },
    { time: '14:45:35', type: 'success', message: 'Browser initialized successfully' },
    { time: '14:45:38', type: 'info', message: 'Navigating to wallester.com' },
    { time: '14:45:42', type: 'success', message: 'Page loaded (2.4s)' },
    { time: '14:46:01', type: 'info', message: 'Form detected: login-form' },
    { time: '14:46:15', type: 'warning', message: 'CAPTCHA detected, waiting...' },
    { time: '14:46:45', type: 'success', message: 'CAPTCHA solved automatically' },
    { time: '14:47:02', type: 'info', message: 'Login successful' },
];

const statusColors = {
    running: { bg: 'bg-success/20', border: 'border-success', text: 'text-success', label: 'Running' },
    idle: { bg: 'bg-warning/20', border: 'border-warning', text: 'text-warning', label: 'Idle' },
    error: { bg: 'bg-destructive/20', border: 'border-destructive', text: 'text-destructive', label: 'Error' },
    retrying: { bg: 'bg-warning/20', border: 'border-warning', text: 'text-warning', label: 'Retrying...' },
};

export default function OCWatchtower() {
    const [sessions, setSessions] = useState(initialSessions);
    const [activeSession, setActiveSession] = useState(sessions[0]);
    const [showNewSessionModal, setShowNewSessionModal] = useState(false);
    const [newSession, setNewSession] = useState({
        name: '',
        url: '',
        profile: 'default',
        timeout: 30,
        proxy: false,
    });

    const handleCreateSession = () => {
        if (!newSession.name || !newSession.url) {
            toast.error('Моля попълнете всички полета');
            return;
        }

        const session = {
            id: Date.now(),
            name: newSession.name,
            status: 'running',
            url: newSession.url,
            duration: '00:00:00',
            profile: newSession.profile,
        };

        setSessions([...sessions, session]);
        setActiveSession(session);
        setShowNewSessionModal(false);
        setNewSession({ name: '', url: '', profile: 'default', timeout: 30, proxy: false });
        toast.success('Сесията е създадена');
    };

    const handleStopSession = (session) => {
        setSessions(sessions.map(s =>
            s.id === session.id ? { ...s, status: 'idle' } : s
        ));
        toast.info(`${session.name} е спряна`);
    };

    const handleDeleteSession = (session) => {
        setSessions(sessions.filter(s => s.id !== session.id));
        if (activeSession?.id === session.id) {
            setActiveSession(sessions[0]);
        }
        toast.success(`${session.name} е изтрита`);
    };

    const handleRetrySession = useCallback((session) => {
        const retryCount = (session.retryCount || 0) + 1;
        const maxRetries = session.maxRetries || 3;

        if (retryCount > maxRetries) {
            toast.error(`${session.name}: max retries (${maxRetries}) достигнати`, {
                description: 'Моля проверете ръчно.',
            });
            return;
        }

        // Set to retrying
        setSessions(prev => prev.map(s =>
            s.id === session.id ? { ...s, status: 'retrying', retryCount, error: `Retry ${retryCount}/${maxRetries}...` } : s
        ));
        toast.info(`${session.name}: retry ${retryCount}/${maxRetries}...`);

        // Simulate retry attempt (2-4 seconds)
        const delay = 2000 + Math.random() * 2000;
        setTimeout(() => {
            // 60% chance of success on retry
            const success = Math.random() > 0.4;
            setSessions(prev => prev.map(s => {
                if (s.id !== session.id) return s;
                if (success) {
                    return { ...s, status: 'running', error: null, retryCount: 0, duration: '00:00:00' };
                }
                return { ...s, status: 'error', error: `Connection timeout (attempt ${retryCount}/${maxRetries})`, retryCount };
            }));

            if (success) {
                toast.success(`${session.name} е свързана успешно!`);
            } else if (retryCount < maxRetries) {
                toast.warning(`${session.name}: retry ${retryCount} неуспешен, опитвам отново...`);
                // Auto-retry after 3 seconds
                setTimeout(() => {
                    setSessions(prev => {
                        const current = prev.find(s => s.id === session.id);
                        if (current && current.status === 'error') {
                            handleRetrySession({ ...current });
                        }
                        return prev;
                    });
                }, 3000);
            } else {
                toast.error(`${session.name}: всички ${maxRetries} опита неуспешни`);
            }
        }, delay);
    }, []);

    return (
        <div className="max-w-7xl mx-auto space-y-6">
            <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
                {/* Left Panel - Sessions List */}
                <div className="lg:col-span-1 space-y-4">
                    <GlassCard>
                        <GlassCardContent className="p-4">
                            <div className="flex items-center justify-between mb-4">
                                <h3 className="font-semibold text-foreground">Сесии</h3>
                                <Button
                                    size="sm"
                                    onClick={() => setShowNewSessionModal(true)}
                                    className="bg-primary hover:bg-primary/90"
                                >
                                    <Plus className="w-4 h-4" />
                                </Button>
                            </div>

                            <div className="space-y-2">
                                {sessions.map((session) => (
                                    <React.Fragment key={session.id}>
                                        <motion.button
                                            onClick={() => setActiveSession(session)}
                                            className={`w-full p-3 rounded-lg border-2 text-left transition-all ${activeSession?.id === session.id
                                                    ? `${statusColors[session.status]?.border} ${statusColors[session.status]?.bg}`
                                                    : 'border-border/30 hover:border-primary/50'
                                                } ${session.status === 'error' ? 'animate-pulse' : ''}`}
                                            whileHover={{ scale: 1.02 }}
                                        >
                                            <div className="flex items-center justify-between mb-1">
                                                <span className="font-medium text-foreground text-sm truncate">
                                                    {session.name}
                                                </span>
                                                <span className={`text-xs ${statusColors[session.status]?.text}`}>
                                                    {statusColors[session.status]?.label}
                                                </span>
                                            </div>
                                            <div className="text-xs text-muted-foreground truncate">
                                                {session.url}
                                            </div>
                                            {session.status === 'error' && session.error && (
                                                <div className="text-xs text-destructive mt-1 truncate">
                                                    {session.error}
                                                </div>
                                            )}
                                            {session.status === 'retrying' && (
                                                <div className="flex items-center gap-1 text-xs text-warning mt-1">
                                                    <RefreshCw className="w-3 h-3 animate-spin" />
                                                    {session.error}
                                                </div>
                                            )}
                                        </motion.button>
                                        {session.status === 'error' && (
                                            <Button
                                                size="sm"
                                                variant="ghost"
                                                className="w-full mt-1 h-7 text-xs text-warning hover:bg-warning/10"
                                                onClick={(e) => {
                                                    e.stopPropagation();
                                                    handleRetrySession(session);
                                                }}
                                            >
                                                <RotateCcw className="w-3 h-3 mr-1" />
                                                Auto-Retry
                                            </Button>
                                        )}
                                    </React.Fragment>
                                ))}
                            </div>
                        </GlassCardContent>
                    </GlassCard>

                    {/* Saved Profiles */}
                    <GlassCard>
                        <GlassCardContent className="p-4">
                            <h3 className="font-semibold text-foreground mb-3 flex items-center gap-2">
                                <Bookmark className="w-4 h-4 text-primary" />
                                Запазени Профили
                            </h3>
                            <div className="space-y-2">
                                {savedProfiles.map((profile) => (
                                    <div
                                        key={profile.name}
                                        className="flex items-center justify-between p-2 rounded-lg bg-secondary/20"
                                    >
                                        <span className="text-sm text-foreground">{profile.name}</span>
                                        <div className="flex items-center gap-2">
                                            {profile.proxy && (
                                                <span className="text-xs px-1.5 py-0.5 rounded bg-accent/20 text-accent">
                                                    Proxy
                                                </span>
                                            )}
                                            <span className="text-xs text-muted-foreground">{profile.timeout}s</span>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </GlassCardContent>
                    </GlassCard>
                </div>

                {/* Main Panel - Live View */}
                <div className="lg:col-span-3 space-y-4">
                    {/* Session Tabs */}
                    <div className="flex items-center gap-2 overflow-x-auto pb-2">
                        {sessions.filter(s => s.status !== 'error' && s.status !== 'retrying').map((session) => (
                            <button
                                key={session.id}
                                onClick={() => setActiveSession(session)}
                                className={`flex items-center gap-2 px-4 py-2 rounded-t-lg transition-all whitespace-nowrap ${activeSession?.id === session.id
                                        ? 'bg-primary/20 text-primary border-b-2 border-primary'
                                        : 'text-muted-foreground hover:text-foreground'
                                    }`}
                            >
                                <div className={`w-2 h-2 rounded-full ${session.status === 'running' ? 'bg-success animate-pulse' : 'bg-warning'
                                    }`} />
                                {session.name}
                            </button>
                        ))}
                    </div>

                    {/* Live View Frame */}
                    <GlassCard className={`${activeSession?.status === 'error'
                            ? 'border-2 border-destructive animate-pulse'
                            : activeSession?.status === 'idle'
                                ? 'border-2 border-warning'
                                : ''
                        }`}>
                        <GlassCardContent className="p-0">
                            {/* Frame Header */}
                            <div className="flex items-center justify-between p-3 border-b border-border/30">
                                <div className="flex items-center gap-3">
                                    <Eye className="w-5 h-5 text-primary" />
                                    <span className="font-medium text-foreground">
                                        {activeSession?.name || 'Няма активна сесия'}
                                    </span>
                                    {activeSession && (
                                        <span className={`text-xs px-2 py-0.5 rounded-full ${statusColors[activeSession.status].bg} ${statusColors[activeSession.status].text}`}>
                                            {statusColors[activeSession.status].label}
                                        </span>
                                    )}
                                </div>
                                <div className="flex items-center gap-2">
                                    {activeSession?.status === 'error' && (
                                        <Button
                                            size="sm"
                                            variant="outline"
                                            className="border-warning/50 text-warning hover:bg-warning/10"
                                            onClick={() => handleRetrySession(activeSession)}
                                        >
                                            <RotateCcw className="w-3 h-3 mr-1" />
                                            Retry ({(activeSession.retryCount || 0)}/{activeSession.maxRetries || 3})
                                        </Button>
                                    )}
                                    {activeSession?.status === 'retrying' && (
                                        <Button size="sm" variant="outline" disabled className="border-warning/50 text-warning">
                                            <RefreshCw className="w-3 h-3 mr-1 animate-spin" />
                                            Retrying...
                                        </Button>
                                    )}
                                    {activeSession?.status === 'running' && (
                                        <Button
                                            size="sm"
                                            variant="outline"
                                            onClick={() => handleStopSession(activeSession)}
                                        >
                                            <Square className="w-3 h-3 mr-1" />
                                            Stop
                                        </Button>
                                    )}
                                    {activeSession && (
                                        <Button
                                            size="sm"
                                            variant="ghost"
                                            className="text-destructive"
                                            onClick={() => handleDeleteSession(activeSession)}
                                        >
                                            <Trash2 className="w-3 h-3" />
                                        </Button>
                                    )}
                                </div>
                            </div>

                            {/* Iframe Placeholder */}
                            <div
                                className="h-[400px] bg-secondary/10 flex items-center justify-center"
                                style={{
                                    backgroundImage: 'repeating-linear-gradient(0deg, transparent, transparent 50px, rgba(108, 156, 255, 0.03) 50px, rgba(108, 156, 255, 0.03) 51px), repeating-linear-gradient(90deg, transparent, transparent 50px, rgba(108, 156, 255, 0.03) 50px, rgba(108, 156, 255, 0.03) 51px)'
                                }}
                            >
                                {activeSession ? (
                                    <div className="text-center">
                                        <Globe className="w-16 h-16 text-primary/30 mx-auto mb-4" />
                                        <p className="text-muted-foreground">
                                            Airtop Live View: <span className="text-primary">{activeSession.url}</span>
                                        </p>
                                        <p className="text-sm text-muted-foreground mt-2">
                                            iframe placeholder (allow="clipboard-read;clipboard-write")
                                        </p>
                                        <div className="flex items-center justify-center gap-2 mt-4">
                                            <Clock className="w-4 h-4 text-muted-foreground" />
                                            <span className="font-mono text-foreground">{activeSession.duration}</span>
                                        </div>
                                    </div>
                                ) : (
                                    <p className="text-muted-foreground">Изберете сесия от списъка</p>
                                )}
                            </div>
                        </GlassCardContent>
                    </GlassCard>

                    {/* Session Log */}
                    <GlassCard>
                        <GlassCardContent className="p-4">
                            <h3 className="font-semibold text-foreground mb-3 flex items-center gap-2">
                                <Settings className="w-4 h-4 text-primary" />
                                Session Log
                            </h3>
                            <div className="h-[200px] overflow-y-auto space-y-1 font-mono text-xs">
                                {sessionLogs.map((log, index) => (
                                    <div
                                        key={index}
                                        className={`flex items-start gap-2 p-2 rounded ${log.type === 'success' ? 'text-success' :
                                                log.type === 'warning' ? 'text-warning' :
                                                    log.type === 'error' ? 'text-destructive' : 'text-muted-foreground'
                                            }`}
                                    >
                                        <span className="text-muted-foreground shrink-0">[{log.time}]</span>
                                        {log.type === 'success' && <CheckCircle2 className="w-3 h-3 shrink-0 mt-0.5" />}
                                        {log.type === 'warning' && <AlertTriangle className="w-3 h-3 shrink-0 mt-0.5" />}
                                        <span>{log.message}</span>
                                    </div>
                                ))}
                            </div>
                        </GlassCardContent>
                    </GlassCard>
                </div>
            </div>

            {/* Auto-Response Rules Section */}
            <div className="mt-8">
                <GlassCard>
                    <GlassCardContent className="p-6">
                        <div className="flex items-center justify-between mb-6">
                            <div>
                                <h3 className="text-lg font-semibold text-foreground flex items-center gap-2">
                                    <Settings className="w-5 h-5 text-primary" />
                                    Auto-Response Rules
                                </h3>
                                <p className="text-sm text-muted-foreground mt-1">
                                    Правила за автоматична реакция чрез n8n интеграция.
                                </p>
                            </div>
                            <Button size="sm" className="bg-primary hover:bg-primary/90">
                                <Plus className="w-4 h-4 mr-1" />
                                Ново Правило
                            </Button>
                        </div>

                        <div className="space-y-3">
                            {[
                                { status: true, condition: 'IF CPU > 80% за 5 мин', action: 'Рестартирай service pm2 + Telegram Alert', color: 'destructive' },
                                { status: true, condition: 'IF Airtop session = Error', action: 'Retry след 30 сек, max 3 пъти', color: 'warning' },
                                { status: false, condition: 'IF Supabase sync failed', action: 'Алармирай + спри зависими workflows', color: 'warning' },
                                { status: true, condition: 'IF Memory > 90%', action: 'Clear cache + restart n8n worker', color: 'destructive' }
                            ].map((rule, idx) => (
                                <div key={idx} className={`flex items-center gap-4 p-4 rounded-xl border ${rule.status ? 'border-primary/30 bg-secondary/10' : 'border-border/30 bg-secondary/5 opacity-60'}`}>
                                    <div className="flex-shrink-0">
                                        <button className={`w-10 h-6 rounded-full relative transition-colors ${rule.status ? 'bg-primary' : 'bg-dark-600'}`}>
                                            <div className={`w-4 h-4 rounded-full bg-white absolute top-1 transition-all ${rule.status ? 'right-1' : 'left-1'}`} />
                                        </button>
                                    </div>
                                    <div className="flex items-center gap-3 flex-1 overflow-x-auto text-sm">
                                        <span className={`px-2.5 py-1 rounded bg-${rule.color}/10 text-${rule.color} font-mono font-medium whitespace-nowrap`}>
                                            {rule.condition}
                                        </span>
                                        <span className="text-muted-foreground font-medium">→</span>
                                        <span className="text-foreground font-medium whitespace-nowrap">
                                            {rule.action}
                                        </span>
                                    </div>
                                    <div className="flex items-center gap-2">
                                        <Button size="icon" variant="ghost" className="h-8 w-8 text-muted-foreground hover:text-primary">
                                            <Settings className="w-4 h-4" />
                                        </Button>
                                        <Button size="icon" variant="ghost" className="h-8 w-8 text-muted-foreground hover:text-destructive">
                                            <Trash2 className="w-4 h-4" />
                                        </Button>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </GlassCardContent>
                </GlassCard>
            </div>

            {/* New Session Modal */}
            <AnimatePresence>
                {showNewSessionModal && (
                    <motion.div
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        exit={{ opacity: 0 }}
                        className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-background/80 backdrop-blur-sm"
                        onClick={() => setShowNewSessionModal(false)}
                    >
                        <motion.div
                            initial={{ scale: 0.9, opacity: 0 }}
                            animate={{ scale: 1, opacity: 1 }}
                            exit={{ scale: 0.9, opacity: 0 }}
                            onClick={(e) => e.stopPropagation()}
                            className="w-full max-w-md"
                        >
                            <GlassCard>
                                <GlassCardContent className="p-6">
                                    <div className="flex items-center justify-between mb-6">
                                        <h3 className="text-lg font-semibold text-foreground flex items-center gap-2">
                                            <Plus className="w-5 h-5 text-primary" />
                                            Нова Airtop Сесия
                                        </h3>
                                        <Button variant="ghost" size="icon" onClick={() => setShowNewSessionModal(false)}>
                                            <X className="w-5 h-5" />
                                        </Button>
                                    </div>

                                    <div className="space-y-4">
                                        <div>
                                            <label className="text-sm text-muted-foreground mb-2 block">Име на сесията</label>
                                            <Input
                                                value={newSession.name}
                                                onChange={(e) => setNewSession({ ...newSession, name: e.target.value })}
                                                placeholder="my-session"
                                                className="bg-secondary/30"
                                            />
                                        </div>

                                        <div>
                                            <label className="text-sm text-muted-foreground mb-2 block">URL</label>
                                            <Input
                                                value={newSession.url}
                                                onChange={(e) => setNewSession({ ...newSession, url: e.target.value })}
                                                placeholder="https://example.com"
                                                className="bg-secondary/30"
                                            />
                                        </div>

                                        <div>
                                            <label className="text-sm text-muted-foreground mb-2 block">Профил</label>
                                            <select
                                                value={newSession.profile}
                                                onChange={(e) => setNewSession({ ...newSession, profile: e.target.value })}
                                                className="w-full p-2 rounded-lg bg-secondary/30 border border-border/30 text-foreground"
                                            >
                                                {savedProfiles.map((p) => (
                                                    <option key={p.name} value={p.name}>{p.name}</option>
                                                ))}
                                            </select>
                                        </div>

                                        <div>
                                            <label className="text-sm text-muted-foreground mb-2 block">Timeout (секунди)</label>
                                            <Input
                                                type="number"
                                                value={newSession.timeout}
                                                onChange={(e) => setNewSession({ ...newSession, timeout: parseInt(e.target.value) })}
                                                className="bg-secondary/30"
                                            />
                                        </div>

                                        <div className="flex items-center gap-3">
                                            <input
                                                type="checkbox"
                                                id="proxy"
                                                checked={newSession.proxy}
                                                onChange={(e) => setNewSession({ ...newSession, proxy: e.target.checked })}
                                                className="w-4 h-4 rounded border-border/30"
                                            />
                                            <label htmlFor="proxy" className="text-sm text-foreground">Използвай Proxy</label>
                                        </div>

                                        <Button
                                            className="w-full bg-primary hover:bg-primary/90"
                                            onClick={handleCreateSession}
                                        >
                                            <Play className="w-4 h-4 mr-2" />
                                            Стартирай Сесия
                                        </Button>
                                    </div>
                                </GlassCardContent>
                            </GlassCard>
                        </motion.div>
                    </motion.div>
                )}
            </AnimatePresence>
        </div>
    );
}
